{
  description = "An opinionated, consumer-clean Nix project template";

  inputs = {
    nixpkgs.url = "github:NixOS/nixpkgs/nixos-unstable";

    flake-parts = {
      url = "github:hercules-ci/flake-parts";
      inputs.nixpkgs-lib.follows = "nixpkgs";
    };
  };

  outputs =
    inputs@{ flake-parts, ... }:
    flake-parts.lib.mkFlake { inherit inputs; } {
      systems = [
        "x86_64-linux"
        "aarch64-linux"
      ];

      imports = [ inputs.flake-parts.flakeModules.partitions ];

      # Development tools do not enter the input closure of package, module,
      # overlay, or library consumers.
      partitionedAttrs = {
        checks = "dev";
        devShells = "dev";
        formatter = "dev";
      };

      partitions.dev = {
        extraInputsFlake = ./dev;
        module = import ./nix/flake/dev-partition.nix;
      };
    };
}

{ inputs, ... }:
{
  imports = [
    inputs.git-hooks.flakeModule
    inputs.treefmt-nix.flakeModule
  ];

  perSystem =
    {
      config,
      pkgs,
      ...
    }:
    {
      # One definition drives `nix fmt` and the treefmt Git hook. The hook is
      # also exercised by the sandboxed pre-commit check below. Formatters and
      # file-oriented linters belong here, not in git-hooks.
      treefmt = {
        projectRootFile = "flake.nix";

        # `checks.pre-commit` already runs the treefmt hook in the sandbox along
        # with Git-specific hooks. Avoid a second derivation that repeats it.
        flakeCheck = false;
        programs = {
          actionlint.enable = true;
          deadnix.enable = true;
          nixfmt.enable = true;
          prettier.enable = true;
          shellcheck.enable = true;
          shfmt.enable = true;
          statix.enable = true;
          taplo.enable = true;
        };
        settings.formatter = {
          shellcheck.includes = [
            "*.sh"
            ".envrc"
          ];
          shfmt.includes = [
            "*.sh"
            ".envrc"
          ];
        };
      };

      pre-commit.settings.hooks = {
        treefmt.enable = true;
        check-added-large-files.enable = true;
        check-merge-conflicts.enable = true;

        flake-check-before-push = {
          enable = true;
          name = "authoritative Nix checks";
          entry = "${pkgs.nix}/bin/nix flake check --print-build-logs";
          always_run = true;
          pass_filenames = false;
          require_serial = true;
          stages = [ "pre-push" ];
        };
      };

      devShells.default = pkgs.mkShell {
        packages = [
          pkgs.nixd
          pkgs.secretspec
        ];
        shellHook = config.pre-commit.installationScript;
      };
    };
}

{
  description = "Neocache development-only inputs";

  inputs = {
    nixpkgs.url = "github:NixOS/nixpkgs/master";
    nix_2_34.url = "github:nixos/nix?ref=2.34-maintenance";

    git-hooks-nix = {
