{
  description = "A Nix-built container sandbox for coding agents";

  inputs = {
    nixpkgs.url = "github:NixOS/nixpkgs/nixos-unstable";

    flake-parts = {
      url = "github:hercules-ci/flake-parts";
      inputs.nixpkgs-lib.follows = "nixpkgs";
    };
  };

  outputs =
    inputs@{ flake-parts, ... }:
    flake-parts.lib.mkFlake { inherit inputs; } {
      systems = [
        "x86_64-linux"
        "aarch64-linux"
      ];

      imports = [
        inputs.flake-parts.flakeModules.partitions
        ./nix/flake/project.nix
      ];

      # Authoring tools stay out of the package and image input graph.
      partitionedAttrs = {
        checks = "dev";
        devShells = "dev";
        formatter = "dev";
      };

      partitions.dev = {
        extraInputsFlake = ./dev;
        module = import ./nix/flake/dev-partition.nix;
      };
    };
}

{
  description = "Agent sandbox development-only inputs";

  inputs = {
    nixpkgs.url = "github:NixOS/nixpkgs/nixos-unstable";

    git-hooks = {
      url = "github:cachix/git-hooks.nix";
      inputs.nixpkgs.follows = "nixpkgs";
    };

    treefmt-nix = {
      url = "github:numtide/treefmt-nix";
      inputs.nixpkgs.follows = "nixpkgs";
    };
  };

  outputs = _: { };
}

use std::env;
use std::io::{self, BufRead, BufReader, Write};
use std::net::{TcpListener, TcpStream};
use std::thread;

const HEALTH_RESPONSE: &[u8] =
    b"HTTP/1.1 200 OK\r\nContent-Type: application/json\r\nContent-Length: 16\r\nConnection: close\r\n\r\n{\"status\":\"ok\"}";
const NOT_FOUND_RESPONSE: &[u8] = b"HTTP/1.1 404 Not Found\r\nContent-Length: 0\r\nConnection: close\r\n\r\n";

fn response_for(request_line: &str) -> &'static [u8] {
    if request_line == "GET /healthz HTTP/1.1" {
        HEALTH_RESPONSE
    } else {
        NOT_FOUND_RESPONSE
    }
}

fn handle_connection(mut stream: TcpStream) -> io::Result<()> {
    let mut request_line = String::new();
    BufReader::new(stream.try_clone()?).read_line(&mut request_line)?;
    stream.write_all(response_for(request_line.trim_end()))?;
    stream.flush()
}

fn main() -> io::Result<()> {
    let address = env::var("AGENT_SANDBOX_LISTEN").unwrap_or_else(|_| "0.0.0.0:8080".into());
    let listener = TcpListener::bind(&address)?;
    eprintln!("agent-sandbox listening on {address}");

    for connection in listener.incoming() {
        match connection {
            Ok(stream) => {
                thread::spawn(move || {
                    if let Err(error) = handle_connection(stream) {
                        eprintln!("request failed: {error}");
                    }
                });
            }
            Err(error) => eprintln!("connection failed: {error}"),
        }
    }

    Ok(())
}

#[cfg(test)]
mod tests {
    use super::{HEALTH_RESPONSE, NOT_FOUND_RESPONSE, response_for};

    #[test]
    fn health_endpoint_is_available() {
        assert_eq!(response_for("GET /healthz HTTP/1.1"), HEALTH_RESPONSE);
    }

    #[test]
    fn unknown_endpoint_is_not_found() {
        assert_eq!(response_for("GET /missing HTTP/1.1"), NOT_FOUND_RESPONSE);
    }
}

{ inputs, ... }:
{
  perSystem =
    { pkgs, ... }:
    let
      inherit (pkgs) lib;

      rustSource = lib.fileset.toSource {
        root = ../..;
        fileset = lib.fileset.unions [
          ../../src
          ../../Cargo.toml
          ../../Cargo.lock
        ];
      };

      agent = pkgs.rustPlatform.buildRustPackage {
        pname = "agent-sandbox";
        version = "0.1.0";
        src = rustSource;
        cargoLock.lockFile = ../../Cargo.lock;
        strictDeps = true;

        meta = {
          description = "Containerized code sandbox service";
          license = lib.licenses.mit;
          mainProgram = "agent-sandbox";
          platforms = lib.platforms.linux;
        };
      };

      python = pkgs.python3.withPackages (pythonPackages: [
        pythonPackages.matplotlib
        pythonPackages.numpy
        pythonPackages.openpyxl
        pythonPackages.orjson
        pythonPackages.pandas
        pythonPackages.pillow
        pythonPackages.pytesseract
        pythonPackages.requests
      ]);

      agentRootfs = pkgs.runCommand "agent-sandbox-rootfs" { } ''
        mkdir -p "$out/etc" "$out/home/user" "$out/usr/bin"
        cat > "$out/etc/passwd" <<'EOF'
        root:x:0:0:root:/root:/bin/sh
        sandbox-manager:x:10001:10001:Sandbox manager:/home/user:/bin/sh
        EOF
        cat > "$out/etc/group" <<'EOF'
        root:x:0:
        sandbox-manager:x:10001:
        EOF
        ln -s ${lib.getExe agent} "$out/usr/bin/agent-sandbox"
      '';

      agentImage = pkgs.dockerTools.buildLayeredImage {
        name = "agent-sandbox";
        tag = "latest";
        contents = [
          agent
          pkgs.cacert
          pkgs.tesseract
          python
        ];
        fakeRootCommands = ''
          ${pkgs.dockerTools.shadowSetup}
          groupadd --gid 10001 --system sandbox-manager
          useradd --uid 10001 --gid sandbox-manager --system \
            --home-dir /home/user sandbox-manager
          mkdir -p ./home/user
          chown 10001:10001 ./home/user
        '';
        config = {
          User = "sandbox-manager";
          Env = [
            "HOME=/home/user"
            "SSL_CERT_FILE=${pkgs.cacert}/etc/ssl/certs/ca-bundle.crt"
          ];
          WorkingDir = "/home/user";
          Entrypoint = [ (lib.getExe agent) ];
          ExposedPorts."8080/tcp" = { };
        };
      };

      nspawnApp = pkgs.writeShellApplication {
        name = "agent-systemd-nspawn";
        runtimeInputs = [ pkgs.systemd ];
        text = ''
          machine="agent-sandbox-$UID"
          command=(
            sudo ${pkgs.systemd}/bin/systemd-nspawn
            --quiet
            --directory=${agentRootfs}
            --volatile=overlay
            --register=no
            --settings=no
            --machine="$machine"
            --bind-ro=/nix/store
            --tmpfs=/home/user:mode=0750,uid=10001,gid=10001
            --setenv=HOME=/home/user
            --setenv=AGENT_SANDBOX_LISTEN=0.0.0.0:8080
            --user=sandbox-manager
            /usr/bin/agent-sandbox
          )

          if [[ "''${1:-}" == "--dry-run" ]]; then
            printf '%q ' "''${command[@]}"
            printf '\n'
            exit 0
          fi

          if ! command -v sudo >/dev/null; then
            echo 'agent-systemd-nspawn requires the host sudo wrapper' >&2
            exit 1
          fi

          echo 'Starting an ephemeral systemd-nspawn unit (wheel authorization required).' >&2
          exec "''${command[@]}"
        '';
      };

      clippyCheck = pkgs.stdenvNoCC.mkDerivation {
        pname = "agent-sandbox-clippy";
        version = "0.1.0";
        src = rustSource;
        nativeBuildInputs = [
          pkgs.cargo
          pkgs.clippy
          pkgs.rustc
        ];
        buildPhase = ''
          runHook preBuild
          export CARGO_HOME="$TMPDIR/cargo-home"
          cargo clippy --all-targets --locked --offline -- -D warnings
          runHook postBuild
        '';
        installPhase = ''
          touch "$out"
        '';
      };

      composeCheck = pkgs.runCommand "agent-sandbox-compose-check" {
        nativeBuildInputs = [ pkgs.podman-compose ];
      } ''
        podman-compose --file ${../../docker-compose.yml} config > "$out"
      '';
    in
    {
      packages = {
        default = agent;
        agent-sandbox = agent;
        agent-image = agentImage;
        oci-image = agentImage;
        agent-rootfs = agentRootfs;
        agent-systemd-nspawn = nspawnApp;
      };

      apps.agent-systemd-nspawn.program = lib.getExe nspawnApp;

      # Consumer outputs are mirrored into the development partition's checks.
      # This keeps `nix flake check` authoritative without putting authoring
      # inputs in the image or package closure.
      _module.args.agentSandboxChecks = {
        inherit agentImage clippyCheck composeCheck;
        agentPackage = agent;
      };
    };
}

{ inputs, ... }:
{
  imports = [
    inputs.git-hooks.flakeModule
    inputs.treefmt-nix.flakeModule
  ];

  perSystem =
    {
      agentSandboxChecks,
      config,
      pkgs,
      ...
    }:
    let
      startPodmanService = pkgs.writeShellApplication {
        name = "agent-podman-service";
        runtimeInputs = [
          pkgs.coreutils
          pkgs.gnugrep
          pkgs.podman
          pkgs.systemd
        ];
        text = ''
          runtime_dir="''${XDG_RUNTIME_DIR:-/run/user/$(id -u)}"
          socket_dir="$runtime_dir/podman"
          socket="$socket_dir/podman.sock"
          marker=/run/agent-sandbox-podman-delegation

          mkdir -p "$socket_dir"

          # Match the neocache development shell's runtime cgroup delegation.
          # The drop-in and marker live under /run and disappear on reboot.
          if [[ ! -e "$marker" ]]; then
            if [[ " $(id -Gn) " != *" wheel "* ]]; then
              echo 'Podman setup requires membership in the wheel group.' >&2
              exit 1
            fi
            if ! command -v sudo >/dev/null; then
              echo 'Podman setup requires the host sudo wrapper.' >&2
              exit 1
            fi

            echo 'Authorizing ephemeral rootless Podman setup for this boot.' >&2
            sudo -v
            printf '[Service]\nDelegate=cpu cpuset io memory pids\n' \
              | sudo tee /run/systemd/system/user@.service.d/agent-sandbox.conf >/dev/null
            sudo systemctl daemon-reload
            sudo touch "$marker"
          fi

          if [[ -S "$socket" ]]; then
            exit 0
          fi

          if ! systemctl --user is-active --quiet agent-sandbox-podman.service; then
            systemd-run --user --quiet --unit=agent-sandbox-podman \
              --property=Delegate=yes \
              podman --log-level=error system service --time=0 "unix://$socket"
          fi

          for _ in $(seq 1 50); do
            [[ -S "$socket" ]] && exit 0
            sleep 0.1
          done

          echo "Podman's Docker-compatible socket did not appear at $socket" >&2
          exit 1
        '';
      };
    in
    {
      treefmt = {
        projectRootFile = "flake.nix";
        flakeCheck = false;
        programs = {
          actionlint.enable = true;
          deadnix.enable = true;
          hadolint.enable = true;
          nixfmt.enable = true;
          prettier.enable = true;
          rustfmt.enable = true;
          shellcheck.enable = true;
          shfmt.enable = true;
          statix.enable = true;
          taplo.enable = true;
        };
        settings.formatter = {
          shellcheck.includes = [
            "*.sh"
            ".envrc"
          ];
          shfmt.includes = [
            "*.sh"
            ".envrc"
          ];
        };
      };

      pre-commit.settings.hooks = {
        treefmt.enable = true;
